// Checkout conversion fix: ensure paidEvents increment on successful payment
const { db } = require('../constants/db');

module.exports = async function processCheckout(session) {
  try {
    // Validate session
    if (!session || !session.id) throw new Error('Invalid session');

    // Process payment (simulated)
    const paymentSuccess = await simulatePayment(session);
    if (!paymentSuccess) throw new Error('Payment failed');

    // Increment paidEvents
    await db.collection('metrics').updateOne(
      { key: 'paidEvents' },
      { $inc: { value: 1 } },
      { upsert: true }
    );

    return { success: true, sessionId: session.id };
  } catch (err) {
    console.error('Checkout conversion error:', err.message);
    return { success: false, error: err.message };
  }
};

